// Package utf8fold compares names the way the Linux utf8 module does for the
// encoding utf8-12.1.0, the one ext4 and F2FS casefold directories use.
//
// The comparison form of a name (Key) is NFD(casefold(NFD(x))) with the default-ignorable code points
// removed, computed per code point from tables generated from the committed Unicode 12.1.0 files
// (tables_gen.go, regenerated byte for byte by TestGenerateTables). Hangul syllables are decomposed
// arithmetically. Combining marks are put in canonical order after the whole name is expanded.
//
// What the kernel does with a name that is not valid UTF-8 was MEASURED in a QEMU guest
// (tools/fixtures/README.md, "Casefold lookup oracle"; 611 rows of kernel-vectors.json.gz, ext4 and F2FS
// agreeing on every one) and is reproduced exactly, no more:
//
//   - a stray continuation byte (0x80-0xBF where a character should start) that comes after at least one
//     byte of the name is an ordinary character that folds to itself and is never dropped; the text around
//     it is folded and normalized, and marks after it are ordered among themselves (FormUnicode);
//   - a stray continuation byte at the start of a name, any other invalid form at the END of a name
//     (a truncated or overlong sequence, a surrogate, a value above U+10FFFF, a lead byte 0xC0-0xFF, with
//     stray bytes before or after the invalid lead), makes the whole name opaque: it is compared byte for
//     byte, no folding, no normalization (FormOpaque);
//   - U+FFFE, U+FFFF and U+10FFFF are ordinary characters.
//
// Every other invalid shape (an invalid byte followed by text or by a valid character, a long invalid tail,
// nothing before the invalid byte, a stray byte next to an ignorable character) was not measured and is
// FormUndecided: Equal reports decided == false and Key refuses. A caller must report that it cannot
// decide; it must never treat the answer as "different" or fold the name by a guess.
//
// A code point assigned after Unicode 12.1 has no case mapping (measured); it still takes part in mark
// ordering. Runs of up to 40 combining marks are ordered completely (measured); the stream-safe limit of
// the kernel is not modelled because no vector shows one.
package utf8fold

import (
	"bytes"
	"slices"
	"unicode/utf8"
)

// Version is the Unicode version of the tables.
const Version = "12.1.0"

// EncodingUTF8v121 is s_encoding of ext4 and F2FS for utf8-12.1.0 (no underscore: the lint's naming rule).
const EncodingUTF8v121 = 1

// MaxName is the longest name Key accepts (a filesystem name is at most 255 bytes).
const MaxName = 255

// Supported reports whether encoding is one this package implements.
func Supported(encoding uint16) bool { return encoding == EncodingUTF8v121 }

type runeRange struct{ lo, hi rune }

type cccRange struct {
	lo, hi rune
	class  uint8
}

// mapEntry names a run of data (off, n) for code point r.
type mapEntry struct {
	r   rune
	off uint32
	n   uint8
}

const (
	hangulS     = 0xAC00
	hangulL     = 0x1100
	hangulV     = 0x1161
	hangulT     = 0x11A7
	hangulTCnt  = 28
	hangulNCnt  = 21 * hangulTCnt
	hangulCount = 19 * hangulNCnt
)

// strayBase marks a stray continuation byte b inside a rune buffer as strayBase+b (above every code point).
const strayBase = 0x110000

// appendHangul appends the jamo of the syllable r.
func appendHangul(dst []rune, r rune) []rune {
	s := r - hangulS
	dst = append(dst, hangulL+s/hangulNCnt, hangulV+(s%hangulNCnt)/hangulTCnt)
	if t := s % hangulTCnt; t != 0 {
		dst = append(dst, hangulT+t)
	}
	return dst
}

// Form is how the kernel compares a name.
type Form int

const (
	// FormUnicode: the name is text (stray continuation bytes after the first byte included); Key is its
	// comparison form.
	FormUnicode Form = iota
	// FormOpaque: the kernel compares the name byte for byte (measured).
	FormOpaque
	// FormUndecided: an invalid shape no measurement covers, or a name longer than MaxName.
	FormUndecided
)

func (f Form) String() string {
	switch f {
	case FormUnicode:
		return "unicode"
	case FormOpaque:
		return "opaque"
	default:
		return "undecided"
	}
}

// maxMeasuredTail is the longest invalid tail any measured row has (F8 88 80 80 80).
const maxMeasuredTail = 5

func isStray(b byte) bool { return b >= 0x80 && b <= 0xBF }

// Classify decides how the kernel compares name; see the package comment.
func Classify(name []byte) Form {
	if len(name) > MaxName {
		return FormUndecided
	}
	leading, strays, ignorable := false, 0, false
	tail := -1
	for i := 0; i < len(name); {
		r, size := utf8.DecodeRune(name[i:])
		if r == utf8.RuneError && size == 1 {
			if isStray(name[i]) {
				if i == 0 {
					leading = true
				}
				strays++
				i++
				continue
			}
			tail = i
			break
		}
		if isIgnorable(r) {
			ignorable = true
		}
		i += size
	}
	if tail < 0 {
		switch {
		case leading:
			return FormOpaque
		case strays > 0 && ignorable:
			return FormUndecided // a stray byte next to an ignorable character was not measured
		}
		return FormUnicode
	}
	// an invalid lead byte at tail: measured only as the END of a name that has text (and no leading stray
	// byte) before it, with a tail of invalid bytes only, at most maxMeasuredTail long
	if tail == 0 || leading || len(name)-tail > maxMeasuredTail {
		return FormUndecided
	}
	for j := tail; j < len(name); {
		r, size := utf8.DecodeRune(name[j:])
		if !(r == utf8.RuneError && size == 1) {
			return FormUndecided // a valid character after the invalid byte
		}
		j++
	}
	return FormOpaque
}

// Key appends the comparison form of name to dst. ok is false, and dst is returned unchanged, unless name
// is FormUnicode; the caller then compares bytes (FormOpaque) or cannot decide (FormUndecided).
func Key(dst, name []byte) (key []byte, ok bool) {
	if Classify(name) != FormUnicode {
		return dst, false
	}
	// at most len(name) code points, each adding at most maxKeyRunesPerRune items: the bound comes from the
	// name that exists, never from anything it declares
	items := make([]item, 0, len(name)*maxKeyRunesPerRune)
	for i := 0; i < len(name); {
		r, size := utf8.DecodeRune(name[i:])
		if r == utf8.RuneError && size == 1 { // a stray continuation byte (Classify checked the rest)
			items = append(items, item{strayBase + rune(name[i]), 0})
			i++
			continue
		}
		i += size
		if isIgnorable(r) {
			continue
		}
		items = appendFolded(items, r)
	}
	reorder(items)
	dst = slices.Grow(dst, len(items)*utf8.UTFMax)
	for _, it := range items {
		if it.r >= strayBase {
			dst = append(dst, byte(it.r-strayBase))
		} else {
			dst = utf8.AppendRune(dst, it.r)
		}
	}
	return dst, true
}

// Equal reports whether a and b are the same name under the kernel's comparison. decided is false when the
// kernel's answer is not known: an identical name is always the same name, an opaque name differs from every
// other name, a text name compares by Key, and anything else is undecided (equal is false then).
//
// One undecided-looking pair is decided because it was measured: an opaque name against the same name with
// one more byte 'z' (the negative controls of every invalid row of the vectors) are different names. The
// kernel meets the invalid byte in the common prefix of both, falls back to comparing bytes, and the lengths
// differ. No other extension is assumed.
func Equal(a, b []byte) (equal, decided bool) {
	if bytes.Equal(a, b) {
		return true, true
	}
	if opaqueWithZ(a, b) || opaqueWithZ(b, a) {
		return false, true
	}
	fa, fb := Classify(a), Classify(b)
	switch {
	case fa == FormUndecided || fb == FormUndecided:
		return false, false
	case fa == FormOpaque || fb == FormOpaque:
		return false, true
	}
	ka, _ := Key(nil, a)
	kb, _ := Key(nil, b)
	return bytes.Equal(ka, kb), true
}

// opaqueWithZ reports whether long is short plus one 'z' and short is an opaque name.
func opaqueWithZ(long, short []byte) bool {
	return len(long) == len(short)+1 && long[len(short)] == 'z' && bytes.HasPrefix(long, short) && Classify(short) == FormOpaque
}

// item is a rune of a key under construction with its canonical combining class.
type item struct {
	r rune
	c uint8
}

// appendFolded appends NFD(fold(NFD(r))) as items.
func appendFolded(dst []item, r rune) []item {
	var first, second [maxKeyRunesPerRune]rune
	for _, a := range appendCanon(first[:0], r) {
		f, ok := lookup(foldIndex, foldRunes, a)
		if !ok {
			dst = append(dst, item{a, ccc(a)})
			continue
		}
		for _, g := range f {
			for _, h := range appendCanon(second[:0], g) {
				dst = append(dst, item{h, ccc(h)})
			}
		}
	}
	return dst
}

// appendCanon appends the full canonical decomposition of r.
func appendCanon(dst []rune, r rune) []rune {
	if r >= hangulS && r < hangulS+hangulCount {
		return appendHangul(dst, r)
	}
	if d, ok := lookup(decompIndex, decompRunes, r); ok {
		return append(dst, d...)
	}
	return append(dst, r)
}

// lookup finds r in a sorted index by binary search.
func lookup(idx []mapEntry, data []rune, r rune) ([]rune, bool) {
	lo, hi := 0, len(idx)
	for lo < hi {
		m := int(uint(lo+hi) >> 1)
		switch e := idx[m]; {
		case e.r == r:
			return data[e.off : e.off+uint32(e.n)], true
		case e.r < r:
			lo = m + 1
		default:
			hi = m
		}
	}
	return nil, false
}

// ccc is the canonical combining class of r.
func ccc(r rune) uint8 {
	if r < 0x300 {
		return 0
	}
	lo, hi := 0, len(cccTable)
	for lo < hi {
		m := int(uint(lo+hi) >> 1)
		switch e := cccTable[m]; {
		case r < e.lo:
			hi = m
		case r > e.hi:
			lo = m + 1
		default:
			return e.class
		}
	}
	return 0
}

func isIgnorable(r rune) bool {
	lo, hi := 0, len(ignorableTable)
	for lo < hi {
		m := int(uint(lo+hi) >> 1)
		switch e := ignorableTable[m]; {
		case r < e.lo:
			hi = m
		case r > e.hi:
			lo = m + 1
		default:
			return true
		}
	}
	return false
}

// reorder puts every run of non-starters in canonical order (a stable insertion sort by class; a run is at
// most the length of the buffer, which is bounded by MaxName*maxKeyRunesPerRune).
func reorder(items []item) {
	for i := 1; i < len(items); i++ {
		if items[i].c == 0 {
			continue
		}
		for j := i; j > 0 && items[j-1].c > items[j].c; j-- {
			items[j-1], items[j] = items[j], items[j-1]
		}
	}
}
